import time
from playwright.sync_api import sync_playwright

def display_gxr_overlay():
    with sync_playwright() as p:
        try:
            # Connect to the existing browser instance running on port 9223
            browser = p.chromium.connect_over_cdp("http://localhost:9223")

            # Use the existing context or create a new one, then open a new tab/window
            context = browser.contexts[0] if browser.contexts else browser.new_context()
            page = context.new_page()

            # Navigate directly to the Google Images search results URL for the 2005 GSX-R bike
            page.goto("https://www.google.com/search?q=2005+suzuki+gsxr+bike&tbm=isch", timeout=60000)
            page.wait_for_load_state("domcontentloaded")
            time.sleep(3)  # Brief pause for dynamic content rendering

            # Find a visible image element
            images = page.locator("img")
            count = images.count()
            img_src = ""

            for i in range(count):
                img = images.nth(i)
                try:
                    if img.is_visible():
                        src = img.get_attribute("src") or img.get_attribute("data-src")
                        if src and src.startswith("http"):
                            img_src = src
                            break
                except Exception:
                    continue

            # Fallback source if none parsed via loop
            if not img_src:
                img_src = "https://www.google.com/images/branding/googlelogo/2x/googlelogo_color_120dp.png"

            # Inject a full-screen semi-transparent overlay with the bike image into the page
            page.evaluate(f"""
                () => {{
                    // Remove existing overlay if any
                    const existing = document.getElementById('lucy-overlay');
                    if (existing) existing.remove();

                    // Create overlay container
                    const overlay = document.createElement('div');
                    overlay.id = 'lucy-overlay';
                    overlay.style.position = 'fixed';
                    overlay.style.top = '0';
                    overlay.style.left = '0';
                    overlay.style.width = '100vw';
                    overlay.style.height = '100vh';
                    overlay.style.backgroundColor = 'rgba(0, 0, 0, 0.85)';
                    overlay.style.zIndex = '999999';
                    overlay.style.display = 'flex';
                    overlay.style.flexDirection = 'column';
                    overlay.style.alignItems = 'center';
                    overlay.style.justifyContent = 'center';
                    overlay.style.cursor = 'pointer';

                    // Create image element
                    const img = document.createElement('img');
                    img.src = '{img_src}';
                    img.style.maxHeight = '80vh';
                    img.style.maxWidth = '80vw';
                    img.style.objectFit = 'contain';
                    img.style.borderRadius = '8px';
                    img.style.boxShadow = '0 4px 20px rgba(0,0,0,0.5)';

                    // Create caption
                    const caption = document.createElement('div');
                    caption.innerText = '2005 Suzuki GSX-R Overlay (Click anywhere to close)';
                    caption.style.color = '#ffffff';
                    caption.style.marginTop = '15px';
                    caption.style.fontFamily = 'sans-serif';
                    caption.style.fontSize = '16px';

                    overlay.appendChild(img);
                    overlay.appendChild(caption);
                    document.body.appendChild(overlay);

                    // Click to dismiss functionality
                    overlay.onclick = () => overlay.remove();
                }}
            """)

            print("Verification successful: 2005 GSX-R bike image overlay displayed on screen.")

        except Exception as e:
            print(f"Error during execution: {e}")
        finally:
            # Keep open for viewing inside the timeout limit
            time.sleep(10)

if __name__ == "__main__":
    display_gxr_overlay()
